function daysToMs(days: number) {
  return days * 86400000;
}

function subscriptionExpiry(start: Date, days: number) {
  return new Date(start.getTime() + daysToMs(days));
}

function calculateTotal(amount: number) {
  const tax = amount * 0.0825;
  return amount + tax;
}

function applyDiscount(amount: number) {
  return amount - 10;
}

// Version A
const MILLIS_PER_DAY = 86400000;
function daysToMs(days: number) {
  return days * MILLIS_PER_DAY;
}

// Version B
function daysToMsB(days: number) {
  return days * 86400000;
}
function subscriptionExpiry(start: Date, days: number) {
  return new Date(start.getTime() + daysToMsB(days));
}
